<script setup lang="ts">
import { computed,onMounted,onUnmounted,reactive,ref } from 'vue';
import { Button,Card,Checkbox,Empty,Input,Modal,Select,Table,message } from 'ant-design-vue';
import type { Assignment,LiveRow,Person,Quiz } from './api';
import { exportCsv,getLive,postLive,statusText } from './api';
const props=defineProps<{room:LiveRow;type:string;platform:boolean}>();const emit=defineEmits<{close:[]}>();
const busy=ref(false);const assignments=ref<Assignment[]>([]);const quizzes=ref<Quiz[]>([]);const people=ref<Person[]>([]);
const submissions=ref<{id:number;nickname:string;content:string;score?:number;feedback?:string}[]>([]);const activeAssignment=ref<number>();
const logs=ref<Record<string,unknown>[]>([]);const employees=ref<{id:number;nickname:string}[]>([]);const selected=ref<number[]>([]);const assistants=ref<number[]>([]);
const search=ref('');const incomplete=ref(false);const reason=ref('');const url=ref(props.room.replayVideoUrl??'');const issue=ref(props.room.replayTask?.issue??'');
const assignment=reactive({title:'',content:'',dueAt:''});const quiz=reactive({question:'',options:'',correctAnswer:0});
const grade=reactive({id:0,score:100,feedback:''});const gradeOpen=ref(false);const push=ref<{server:string;streamKey:string}>();
const filtered=computed(()=>people.value.filter(p=>(!search.value||`${p.nickname} ${p.userId}`.includes(search.value))&&(!incomplete.value||!p.completed)));
async function run(fn:()=>Promise<unknown>){if(busy.value)return;busy.value=true;try{await fn();}finally{busy.value=false;}}
async function load(){const roomId=props.room.id;
 if(props.type==='homework')assignments.value=await getLive('assignments',{roomId,managed:true});
 if(props.type==='employees'){employees.value=await getLive('employees');people.value=await getLive('records',{roomId});}
 if(props.type==='control'){people.value=await getLive('participants',{roomId});quizzes.value=await getLive('quizzes',{roomId,managed:true});logs.value=await getLive('moderation',{roomId});}
 if(props.type==='push')push.value=await getLive('stream/publish',{roomId});
}
async function showSubmissions(id:number){activeAssignment.value=id;submissions.value=await getLive('submissions',{assignmentId:id});}
async function batch(path:string){const result=await postLive(path,{roomId:props.room.id,userIds:selected.value});message.success(path==='remind'?`已发送 ${result} 条督促提醒`:'批量预约成功');selected.value=[];await load();}
async function moderate(p:Person,action:string){await postLive('moderation',{roomId:props.room.id,tenantId:p.tenantId,userId:p.userId,action,reason:reason.value});await load();message.success('场控操作已记录');}
function download(){exportCsv('企业直播学习记录',['员工','直播有效秒','回放有效秒','提交作业数','作业总数','已批阅'],filtered.value.map(p=>[p.nickname,p.liveSeconds,p.replaySeconds,p.submitted,p.assignmentCount,p.graded]));}
let timer:ReturnType<typeof setInterval>|undefined;
onMounted(async()=>{await load();if(props.type==='control')timer=setInterval(()=>load().catch(()=>undefined),10000);});onUnmounted(()=>clearInterval(timer));
</script>
<template>
 <Modal open :title="room.title" :width="1000" :footer="null" @cancel="emit('close')">
  <Card v-if="type==='push'" title="OBS 推流配置"><p>点击开播后，在 OBS 中开始推流。使用 H.264 视频和 AAC 音频编码。</p><p>服务器：<code>{{push?.server}}</code></p><label>串流密钥<Input.Password :value="push?.streamKey" readonly/></label><p class="muted">密钥仅供讲师使用。结束直播后服务器关闭推流并归档录像。</p><p v-if="room.streamUrl && !room.streamUrl.includes('/live-media/')">此直播使用外部播放地址。请在对应媒体服务推流并提供录制文件。</p></Card>
  <template v-if="type==='replay'"><p>任务状态：{{statusText(room.replayTask?.status??'awaiting_recording')}}</p><div class="form"><label>回放地址<Input v-model:value="url"/></label><label>异常反馈<Input.TextArea v-model:value="issue"/></label><div class="toolbar"><Button type="primary" :loading="busy" @click="run(async()=>{await postLive('replay/save',{roomId:room.id,url,issue});emit('close');})">保存归档</Button><Button v-if="room.canManage" @click="run(async()=>{await postLive('replay/toggle',{id:room.id,enabled:!room.replayEnabled});emit('close');})">{{room.replayEnabled?'停用回放':'恢复回放'}}</Button><Button v-if="platform" @click="run(async()=>{await postLive('replay/review',{id:room.id,status:'approved',comment:issue});emit('close');})">审核通过</Button><Button v-if="platform" danger @click="run(async()=>{await postLive('replay/review',{id:room.id,status:'rejected',comment:issue});emit('close');})">驳回（填写原因）</Button></div></div></template>
  <template v-if="type==='homework'"><div class="form"><Input v-model:value="assignment.title" placeholder="作业标题"/><Input.TextArea v-model:value="assignment.content" placeholder="题目及作答要求"/><label>截止时间<input v-model="assignment.dueAt" type="datetime-local"/></label><Button type="primary" :loading="busy" @click="run(async()=>{await postLive('assignment/save',{roomId:room.id,...assignment,dueAt:new Date(assignment.dueAt).getTime()});Object.assign(assignment,{title:'',content:'',dueAt:''});await load();})">发布作业</Button></div><Card v-for="a in assignments" :key="a.id" :title="a.title" class="mt-4"><p class="whitespace-pre-wrap">{{a.content}}</p><p>{{a.dueAt}} 截止</p><Button @click="showSubmissions(a.id)">查看提交与批阅</Button></Card><Empty v-if="activeAssignment && !submissions.length" description="暂无学员提交"/><Card v-for="s in submissions" :key="s.id" :title="s.nickname" class="mt-3"><p class="whitespace-pre-wrap">{{s.content}}</p><p v-if="s.feedback">{{s.score}} 分 · {{s.feedback}}</p><Button @click="Object.assign(grade,{id:s.id,score:s.score??100,feedback:s.feedback??''});gradeOpen=true">批阅</Button></Card></template>
  <template v-if="type==='employees'"><div class="toolbar"><Select v-model:value="selected" mode="multiple" show-search option-filter-prop="label" :options="employees.map(e=>({value:e.id,label:e.nickname}))" placeholder="选择本企业员工" style="min-width:360px"/><Button v-if="room.status===0" :disabled="!selected.length" @click="run(()=>batch('booking/batch'))">批量预约</Button><Button :disabled="!selected.length" @click="run(()=>batch('remind'))">督促未完成员工</Button></div><div class="toolbar"><Input v-model:value="search" placeholder="筛选姓名或编号" style="width:200px"/><Checkbox v-model:checked="incomplete">仅未完成</Checkbox><Button @click="load">刷新</Button><Button @click="download">导出筛选结果</Button></div><Table :data-source="filtered" :row-key="(p:Person)=>`${p.tenantId}-${p.userId}`" :columns="[{title:'员工',dataIndex:'nickname'},{title:'直播有效秒',dataIndex:'liveSeconds'},{title:'回放有效秒',dataIndex:'replaySeconds'},{title:'已提交作业',dataIndex:'submitted'},{title:'作业总数',dataIndex:'assignmentCount'},{title:'已批阅',dataIndex:'graded'}]"/></template>
  <template v-if="type==='control'"><div v-if="room.canManage" class="toolbar"><Button @click="run(async()=>{employees=await getLive('assistant-candidates',{roomId:room.id});assistants=await getLive('assistants',{roomId:room.id});})">配置助教</Button><Select v-if="employees.length" v-model:value="assistants" mode="multiple" :options="employees.map(e=>({value:e.id,label:e.nickname}))" placeholder="选择助教" style="min-width:250px"/><Button v-if="employees.length" @click="run(async()=>{await postLive('assistants',{roomId:room.id,userIds:assistants});message.success('助教已保存');})">保存助教</Button></div><div class="toolbar"><Input v-model:value="reason" placeholder="场控原因（必填）"/><Button @click="load">刷新场控数据</Button></div><Table :data-source="people" :row-key="(p:Person)=>`${p.tenantId}-${p.userId}`" :columns="[{title:'学员',dataIndex:'nickname'},{title:'操作',key:'actions'}]"><template #bodyCell="{column,record}"><div v-if="column.key==='actions'" class="toolbar"><Button v-for="a in [{key:'mute',name:'禁言'},{key:'unmute',name:'解除禁言'},{key:'kick',name:'踢出'},{key:'restore',name:'允许进入'}]" :key="a.key" :disabled="!reason.trim()" @click="run(()=>moderate(record,a.key))">{{a.name}}</Button></div></template></Table><Card title="发布随堂测验"><div class="form"><Input v-model:value="quiz.question" placeholder="题目"/><Input.TextArea v-model:value="quiz.options" placeholder="每行一个选项，2–6 项"/><label>正确选项（从 0 开始）<input v-model.number="quiz.correctAnswer" type="number" min="0" max="5"/></label><Button :loading="busy" @click="run(async()=>{await postLive('quiz/save',{roomId:room.id,...quiz,options:quiz.options.split('\n').map(s=>s.trim()).filter(Boolean)});await load();})">发布测验</Button></div></Card><Card v-for="q in quizzes" :key="q.id" :title="q.question" class="mt-3">参与 {{q.answerCount}} 人 · 答对 {{q.correctCount}} 人</Card><Card title="场控日志" class="mt-3"><p v-for="l in logs" :key="String(l.id)">{{l.createTime}} · 用户 {{l.userId}} · {{l.action}} · {{l.reason}}</p><Empty v-if="!logs.length" description="暂无场控操作"/></Card></template>
  <Modal v-model:open="gradeOpen" title="批阅作业" :confirm-loading="busy" @ok="run(async()=>{await postLive('submission/grade',grade);gradeOpen=false;await showSubmissions(activeAssignment!);})"><div class="form"><label>分数<input v-model.number="grade.score" type="number" min="0" max="100"/></label><label>评语<Input.TextArea v-model:value="grade.feedback" :rows="4"/></label></div></Modal>
 </Modal>
</template>
<style scoped>.toolbar{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:14px 0}.form{display:grid;gap:12px}.form label{display:grid;gap:5px}.form input{border:1px solid #d9d9d9;border-radius:6px;padding:7px;background:transparent}.muted{color:#738195;margin-top:15px}</style>
